func genKeyBinary(t *testing.T, publicName string) (configList string, raw []byte) {
	configList, keyPem, err := GenECHConfig(publicName)
	require.NoError(t, err)
	block, _ := pem.Decode([]byte(keyPem))
	require.NotNil(t, block)
	return configList, block.Bytes
}

func TestLoadECHKeyFormats(t *testing.T) {
	_, keyPem, err := GenECHConfig("example.com")
	require.NoError(t, err)
	_, raw1 := genKeyBinary(t, "a.example.com")
	_, raw2 := genKeyBinary(t, "b.example.com")
	multi := append(append([]byte{}, raw1...), raw2...)
	b64Multi := base64.StdEncoding.EncodeToString(multi)

	for _, tt := range []struct {
		name string
		key  string
		n    int
	}{
		{"pem", keyPem, 1},
		{"pem without trailing newline", strings.TrimSpace(keyPem), 1},
		{"xray pem with configs block", xrayECHPem, 1},
		{"xray base64", xrayECHServerKeys, 1},
		{"xray base64 with spaces", "  " + xrayECHServerKeys + "\n", 1},
		{"base64 wrapped", b64Multi[:40] + "\n" + b64Multi[40:], 2},
		{"base64 no padding", strings.TrimRight(xrayECHServerKeys, "="), 1},
		{"base64 multiple keys", b64Multi, 2},
		{"pem multiple keys", string(pem.EncodeToMemory(&pem.Block{Type: "ECH KEYS", Bytes: multi})), 2},
	} {
		t.Run(tt.name, func(t *testing.T) {
			keys, err := loadECHKey([]byte(tt.key))
			require.NoError(t, err)
			assert.Len(t, keys, tt.n)
		})
	}

	for _, tt := range []struct{ name, key string }{
		{"empty", "  \n"},
		{"garbage", "not ech keys!"},
		{"configs pem only", xrayECHPem[:strings.Index(xrayECHPem, "-----BEGIN ECH KEYS")]},
		{"wrong pem type", string(pem.EncodeToMemory(&pem.Block{Type: "PRIVATE KEY", Bytes: raw1}))},
		{"two keys blocks", keyPem + keyPem},
		{"pem with trailing junk", keyPem + "junk"},
		{"truncated base64", base64.StdEncoding.EncodeToString(raw1[:len(raw1)-3])},
		{"config list instead of keys", xrayECHConfigList},
		{"bad config", base64.StdEncoding.EncodeToString([]byte{0, 1, 7, 0, 2, 0xfe, 0x0d})},
	} {
		t.Run("invalid "+tt.name, func(t *testing.T) {
			_, err := loadECHKey([]byte(tt.key))
			assert.Error(t, err)
		})
	}
}

func TestLoadECHKeyInlineAndFile(t *testing.T) {
	var cfg tls.Config
	require.NoError(t, LoadECHKey(xrayECHServerKeys, &cfg))
	keys, err := cfg.GetEncryptedClientHelloKeys(nil)
	require.NoError(t, err)
	assert.Len(t, keys, 1)

	dir := t.TempDir()
	oldHome := C.Path.HomeDir()
	C.SetHomeDir(dir)
	defer C.SetHomeDir(oldHome)
	path := filepath.Join(dir, "ech.key")
	require.NoError(t, os.WriteFile(path, []byte(xrayECHServerKeys+"\n"), 0o600))
	var cfg2 tls.Config
	require.NoError(t, LoadECHKey(path, &cfg2))
	keys, err = cfg2.GetEncryptedClientHelloKeys(nil)
	require.NoError(t, err)
	assert.Len(t, keys, 1)

	assert.Error(t, LoadECHKey(filepath.Join(dir, "missing.key"), &tls.Config{}))
}

// TestECHHandshakeXrayKeys runs a TLS handshake against a server loaded with
// Xray echServerKeys, using the config list printed next to them.
func TestECHHandshakeXrayKeys(t *testing.T) {
	cert := selfSignedCert(t, "example.com")

	for _, tt := range []struct{ name, key, configList string }{
		{"xray base64", xrayECHServerKeys, xrayECHConfigList},
		{"xray pem", xrayECHPem, base64.StdEncoding.EncodeToString(mustPemBlock(t, xrayECHPem, "ECH CONFIGS"))},
	} {
		t.Run(tt.name, func(t *testing.T) {
			serverCfg := &tls.Config{Certificates: []tls.Certificate{cert}, MinVersion: tls.VersionTLS13}
			require.NoError(t, LoadECHKey(tt.key, serverCfg))
			list, err := base64.StdEncoding.DecodeString(tt.configList)
			require.NoError(t, err)

			c1, c2 := net.Pipe()
			defer c1.Close()
			defer c2.Close()
			errCh := make(chan error, 1)
			go func() {
				s := tls.Server(c2, serverCfg)
				errCh <- s.Handshake()
			}()
			client := tls.Client(c1, &tls.Config{
				ServerName:                     "secret.example.org",
				InsecureSkipVerify:             true,
				EncryptedClientHelloConfigList: list,
				MinVersion:                     tls.VersionTLS13,
			})
			require.NoError(t, client.Handshake())
			require.NoError(t, <-errCh)
			assert.True(t, client.ConnectionState().ECHAccepted)
		})
	}
}

func mustPemBlock(t *testing.T, data, typ string) []byte {
	rest := []byte(data)
	for {
		var block *pem.Block
		block, rest = pem.Decode(rest)
		require.NotNil(t, block)
		if block.Type == typ {
			return block.Bytes
		}
	}
}

func selfSignedCert(t *testing.T, name string) tls.Certificate {
	key, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	require.NoError(t, err)
	tmpl := &x509.Certificate{
		SerialNumber: big.NewInt(1),
		Subject:      pkix.Name{CommonName: name},
		DNSNames:     []string{name, "secret.example.org"},
		NotBefore:    time.Now().Add(-time.Hour),
		NotAfter:     time.Now().Add(time.Hour),
	}
	der, err := x509.CreateCertificate(rand.Reader, tmpl, tmpl, &key.PublicKey, key)
	require.NoError(t, err)
	return tls.Certificate{Certificate: [][]byte{der}, PrivateKey: key}
}
